"""Concrete traces for every graph node; dimensions are illustrative unless stated."""
from copy import deepcopy


def extend(diagrams, topics):
    models = {d['id']: d for d in diagrams}
    notes = {t['id']: t['walkthrough'] for t in topics}

    def D(key, scenario, examples):
        d = models[key]
        assert len(d['nodes']) == len(examples), key
        d['scenario'] = scenario
        for n, example in zip(d['nodes'], examples):
            n['workedExample'] = example

    D('bert', 'Учебная последовательность из 5 позиций, d=8, две головы; словарь V=100. Формы включают batch B=1.', [
      'Вход [CLS], кот, [MASK], [SEP], [PAD] содержит пять token IDs. Для MLM target позиции MASK хранит исходное слово; PAD не считается обычным контекстом.',
      'Lookup token/position/segment возвращает по [1,5,8]. Складываем покомпонентно, а не concatenate: итоговая ширина остаётся 8. Нормировка и dropout не добавляют токенов.',
      'Q,K,V после разбиения на головы имеют [1,2,5,4]. Реальные queries сравниваются с доступными keys слева и справа; PAD-key закрыт. Concat и проекция возвращают [1,5,8].',
      'Если вход токена [1,2], а attention-поправка [0.1,−0.2], сумма [1.1,1.8] затем нормируется. Это post-norm: LN выполняется после сложения.',
      'Один и тот же MLP 8→32→8 с GELU применяется к каждой из пяти позиций. Соседняя позиция здесь не читается: обмен уже произошёл в attention.',
      'К FFN-выходу прибавляем его вход и делаем LN. Получаем пять контекстных векторов ширины 8; следующий encoder block снова обрабатывает их вместе.',
      'Берём hidden state MASK формы [1,8], преобразуем в [1,100] logits. Loss сравнивает его с исходным token ID; сама метка не подаётся в encoder на этой позиции.',
      'Берём pooled CLS и получаем два logits: IsNext/NotNext. Это исходная задача отношения двух сегментов, а не классификация каждого слова.',
      'MLM loss берётся по выбранным позициям, NSP — по паре сегментов. Для обычного применения модели labels и вычисление предобучающего loss не обязательны.'
    ])
    D('attention', 'Одна голова: q=1, K=[0, ln(3)], V=[10,20], d_k=1. Цель — увидеть каждый промежуточный результат.', [
      'Q имеет [1,1]: один запрос определит один выход. В self-attention он вычислен из текущего токена, в cross-attention может происходить из decoder.',
      'K имеет [2,1]: сравниваем один query с двумя адресами содержимого. Если поменять key, изменится вес чтения, даже при неизменном V.',
      'V имеет [2,1]: это два сообщения 10 и 20. Их значения не обязаны совпадать с keys; они участвуют в сумме после вычисления весов.',
      'Скалярные произведения дают [0,ln(3)]. Общая форма scores [n,m]=[1,2]; деление на sqrt(d_k) здесь равно делению на 1.',
      'Если второй key запрещён, scores становятся [0,−∞]. Маска не вычитает число из V: она запрещает связь query→key до нормировки весов.',
      'Без запрета exp(scores)=[1,3], сумма 4, веса [0.25,0.75]. При запрете второго key получаем [1,0]. В каждой допустимой строке сумма весов равна 1.',
      'Без маски выход 0.25·10+0.75·20=17.5; с запретом — 10. Один query вернул один value-вектор, а не весь список исходных значений.'
    ])
